data.solution:
string = input()
array = string.replace('\\n',' ').split()
result = []
for l,r in zip(array,array[1:]):
    if not l[-1].isalpha():
        continue
    if not r[-1].isalpha():
        r_clean=r[:-1]
    else:
        r_clean=r
    if l.lower()==r_clean.lower():
        result.append(l)
if result:
    for i in result:
        print(i)
else:
    print('No repeats!')
